app.get('/v1/entitlements', authenticateUser, async (req, res) => {
    const uid = req.user.uid;

    try {
        if (admin && admin.apps && admin.apps.length > 0) {
            const doc = await admin.firestore().collection('users').doc(uid).collection('entitlements').doc('vip').get();
            if (doc.exists) {
                const data = doc.data();
                const isExpired = data.expiryTimeMillis && data.expiryTimeMillis <= Date.now();
                if (data.isVipActive === true && (!data.expiryTimeMillis || !isExpired)) {
                    return res.json({
                        isVip: true,
                        verifiedAt: data.verifiedAt || null,
                        source: data.source || 'google_play',
                        expiryTimeMillis: data.expiryTimeMillis || null
                    });
                }
            }
            const fresh = await recomputeUserEntitlement(uid);
            if (fresh.isVip) {
                return res.json({
                    isVip: true,
                    source: 'google_play',
                    expiryTimeMillis: fresh.expiryTimeMillis || null
                });
            }
        } else if (config.allowMocks) {
            const ent = inMemoryDb.entitlements.get(uid);
            if (ent) {
                const isExpired = ent.expiryTimeMillis && ent.expiryTimeMillis <= Date.now();
                if (ent.isVipActive === true && (!ent.expiryTimeMillis || !isExpired)) {
                    return res.json({
                        isVip: true,
