                        source: ent.source || 'in_memory',
                        expiryTimeMillis: ent.expiryTimeMillis || null
                    });
                }
            }
            const fresh = await recomputeUserEntitlement(uid);
            if (fresh.isVip) {
                return res.json({
                    isVip: true,
                    source: 'in_memory',
                    expiryTimeMillis: fresh.expiryTimeMillis || null
                });
            }
        }

        return res.json({ isVip: false });
