private fun executeBackup(
    activity: Activity,
    lifecycleOwner: LifecycleOwner,
    game: GameRecord,
    authRepo: AuthRepository,
    userUid: String,
    driveAuthManager: DriveAuthorizationManager,
    backupType: String,
    onComplete: (() -> Unit)?
) {
    val progressDialogView = createProgressDialogView(activity, activity.getString(R.string.backup_uploading, 0))
    val dialog = MaterialAlertDialogBuilder(activity)
        .setView(progressDialogView.root)
        .setCancelable(false)
        .create()

    }

    val subsParams = QueryPurchasesParams.newBuilder()
        .setProductType(BillingClient.ProductType.SUBS)
        .build()

    billingClient.queryPurchasesAsync(subsParams) { _, subPurchases ->
        val inAppParams = QueryPurchasesParams.newBuilder()
            .setProductType(BillingClient.ProductType.INAPP)
            .build()

        billingClient.queryPurchasesAsync(inAppParams) { _, inAppPurchases ->
            val allPurchases = (subPurchases.orEmpty() + inAppPurchases.orEmpty()).distinctBy { it.purchaseToken }
            val vipPurchases = allPurchases.filter { purchase ->
                purchase.products.any { it in VIP_PRODUCT_IDS } &&
                    purchase.purchaseState == Purchase.PurchaseState.PURCHASED
            }

            if (vipPurchases.isEmpty()) {
                onFinished?.invoke(false)
            } else {
                // Verify with server before reporting success (F07)
                var verifiedCount = 0
                var anySuccess = false
                for (p in vipPurchases) {
                    handlePurchase(p) { success ->
                        synchronized(this) {
                            verifiedCount++
                            if (success) anySuccess = true
                            if (verifiedCount == vipPurchases.size) {
                                onFinished?.invoke(anySuccess)
                            }
                        }
                    }
                }
            }
        }
    }
}

