suspend fun refreshEntitlement(authRepo: AuthRepository): Boolean = withContext(Dispatchers.IO) {
    val user = authRepo.getCurrentUser() ?: return@withContext false
    val backendUrl = getBackendUrl() ?: return@withContext false
    val idToken = authRepo.getIdToken() ?: return@withContext false

    if (currentActiveUid == null) {
        currentActiveUid = user.uid
    }
    val requestGeneration = currentSessionGeneration
    val requestUid = user.uid

    try {
        val request = Request.Builder()
            .url("$backendUrl/v1/entitlements")
            .header("Authorization", "Bearer $idToken")
            .get()
            .build()

        httpClient.newCall(request).execute().use { response ->
            if (response.isSuccessful) {
                val body = response.body?.string() ?: ""
                val json = JSONObject(body)
                val isVip = json.optBoolean("isVip", false)

                synchronized(this@EntitlementRepository) {
                    if (currentSessionGeneration == requestGeneration && currentActiveUid == requestUid) {
                        prefs.edit().putBoolean(KEY_IS_VIP_PREFIX + requestUid, isVip).apply()
                        _isVipActive.value = isVip
                        return@withContext isVip
                    } else {
                        Log.w(TAG, "Ignoring stale refresh response because user session changed.")
                        return@withContext false
                    }
                }
            }
        }
    } catch (e: Exception) {
        if (e is kotlinx.coroutines.CancellationException) throw e
        Log.w(TAG, "Failed to refresh entitlement from server: ${e.message}")
    }
    return@withContext prefs.getBoolean(KEY_IS_VIP_PREFIX + requestUid, false)
}

